            if replica_target == current and other_ci not in group:
                group.add(other_ci)
                queue.append(other_ci)
        # Find what current is a replica of
        if current in replica_of:
            target = replica_of[current]
            if target not in group:
                group.add(target)
                queue.append(target)
    return group

# Function to get footprint (regions where replica group is deployed)
